3: export function validateGraph(graph, objective) {
4:   if (!graph || graph.objective !== objective || !nonempty(graph.summary)
5:     || !Array.isArray(graph.nodes) || graph.nodes.length < 1 || graph.nodes.length > 8) {
6:     throw new Error('Expected the original objective, a research summary, and 1–8 nodes.');
7:   }
8:   const nodes = new Map();
9:   for (const node of graph.nodes) {
10:     if (!node || typeof node.id !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(node.id)
11:       || !nonempty(node.title) || !nonempty(node.reason)
12:       || !Array.isArray(node.evidence) || !node.evidence.length || !node.evidence.every(nonempty)
13:       || !Array.isArray(node.dependsOn) || !node.dependsOn.every(nonempty) || nodes.has(node.id)) {
14:       throw new Error('Each node needs a unique slug id, title, reason, evidence, and dependsOn array.');
15:     }
16:     nodes.set(node.id, node);
17:   }
18:   const visiting = new Set();
19:   const visited = new Set();
20:   function visit(id) {
21:     if (!nodes.has(id)) throw new Error(`Unknown dependency: ${id}`);
22:     if (visiting.has(id)) throw new Error(`Dependency cycle: ${id}`);
23:     if (visited.has(id)) return;
24:     visiting.add(id);
25:     for (const dependency of nodes.get(id).dependsOn) visit(dependency);
26:     visiting.delete(id);
27:     visited.add(id);
28:   }
29:   for (const id of nodes.keys()) visit(id);
30:   return graph;
31: }
