31: function allowed(path) {
32:   return !path.split('/').some(part =>
33:     /^(?:\.git|\.tag|\.env(?:\..*)?|\.ssh|\.aws|\.npmrc|\.netrc|secrets?(?:\..*)?|credentials?(?:\..*)?|id_rsa|id_ed25519)$/i.test(part))
