38: export async function repositoryTools(directory) {
39:   const root = await realpath(directory);
40:   const git = async args => (await exec('git', [
41:     '--no-pager', '-c', 'core.fsmonitor=false', '-c', 'log.showSignature=false', '-C', root, ...args,
42:   ], { maxBuffer: 2 * 1024 * 1024, timeout: 10_000 })).stdout;
43:   if ((await git(['rev-parse', '--show-toplevel'])).trim() !== root) {
44:     throw new Error('Choose the repository root directory.');
45:   }
46:   const files = [...new Set((await git(['ls-files', '-z'])).split('\0').filter(path => path && allowed(path)))].sort();
47:   const known = new Set(files);
48:   async function textFile(path) {
49:     if (!known.has(path)) throw new Error('Choose a listed tracked file.');
50:     const absolute = resolve(root, path);
51:     if (await realpath(absolute) !== absolute) throw new Error('Symlinks are not readable.');
52:     const handle = await open(absolute, 'r');
53:     try {
54:       const stat = await handle.stat();
55:       if (!stat.isFile() || stat.size > 256 * 1024) throw new Error('Only text files up to 256 KiB are readable.');
56:       const text = await handle.readFile('utf8');
57:       if (text.includes('\0')) throw new Error('Binary files are not readable.');
58:       return text.split('\n');
59:     } finally {
60:       await handle.close();
61:     }
62:   }
63:   return async function investigate(name, args) {
64:     if (!args || typeof args !== 'object' || Array.isArray(args)) throw new Error('Expected an argument object.');
65:     switch (name) {
66:       case 'list_files': {
67:         const offset = args.offset ?? 0;
68:         if (!Number.isInteger(offset) || offset < 0) throw new Error('Invalid offset.');
69:         return JSON.stringify({ files: files.slice(offset, offset + 100), total: files.length, nextOffset: offset + 100 < files.length ? offset + 100 : null });
70:       }
71:       case 'read_file': {
72:         const start = args.startLine ?? 1;
73:         if (!Number.isInteger(start) || start < 1) throw new Error('Invalid startLine.');
74:         const lines = await textFile(args.path);
75:         if (start > lines.length) {
76:           return `[No lines read: ${args.path} has ${lines.length} lines, so startLine ${start} is past the end.]`;
77:         }
78:         // Two dogfood runs ignored an explicit instruction to paginate, so the window itself
79:         // is the problem: deliver whole files rather than asking the model to ask again.
80:         // Oversized reads are still bounded, and the planner's request-byte guard still applies.
81:         const delivered = [];
82:         let size = 0;
83:         for (const [index, line] of lines.slice(start - 1).entries()) {
84:           const numbered = `${start + index}: ${line}`;
85:           const text = numbered.length > READ_BYTES ? `${numbered.slice(0, READ_BYTES)} …[long line truncated]` : numbered;
86:           if (delivered.length && size + text.length + 1 > READ_BYTES) break;
87:           delivered.push(text);
88:           size += text.length + 1;
89:         }
90:         const last = start + delivered.length - 1;
91:         const remaining = lines.length - last;
92:         return delivered.join('\n') + '\n' + (remaining > 0
93:           ? `[PARTIAL READ: lines ${start}-${last} of ${lines.length}. The remaining ${remaining} lines of ${args.path} have NOT been shown. Call read_file with path "${args.path}" and startLine ${last + 1} to read them.]`
94:           : `[Lines ${start}-${last} of ${lines.length}. End of ${args.path}; the whole file from line ${start} has been shown.]`);
95:       }
96:       case 'search': {
97:         if (typeof args.text !== 'string' || !args.text.trim()) throw new Error('Expected nonempty search text.');
98:         const matches = [];
99:         for (const path of files) {
100:           let lines;
101:           try { lines = await textFile(path); } catch { continue; }
102:           for (const [index, line] of lines.entries()) {
103:             if (line.toLowerCase().includes(args.text.toLowerCase())) {
104:               matches.push(`${path}:${index + 1}: ${line.slice(0, 300)}`);
105:               if (matches.length === 50) return matches.join('\n') + '\n[Stopped at 50 matches]';
106:             }
107:           }
108:         }
109:         return matches.join('\n') || 'No matches in readable tracked files.';
110:       }
111:       case 'history':
112:         if (args.path !== undefined && !known.has(args.path)) throw new Error('Choose a listed tracked file.');
113:         return (await git(['log', '-10', '--format=%h %s', '--', ...(args.path ? [args.path] : [])])).slice(0, 20_000);
114:       default:
115:         throw new Error(`Unknown repository tool: ${name}`);
116:     }
117:   };
118: }
